sys_ui_action.script:
(function() {
    // Check for existing open maintenance ticket
    var existing = new GlideRecord('x_1903615_worksp_0_workspace_maintenance');
    existing.addQuery('reservation', current.sys_id);
    existing.addQuery('ticket_status', 'open');
    existing.query();
    if (existing.hasNext()) {
        gs.addErrorMessage('An open maintenance ticket already exists for this reservation.');
        action.setRedirectURL(current);
        return;
    }

    // Validate maintenance issue comment exists
    if (!current.close_notes || current.close_notes == '') {
        gs.addErrorMessage('A maintenance issue comment is required.');
        action.setRedirectURL(current);
        return;
    }

    var maint = new GlideRecord('x_1903615_worksp_0_workspace_maintenance');
    maint.initialize();
    maint.reservation       = current.sys_id;
    maint.workspace         = current.workspace;
    maint.workspace_status  = 'in_maintenance';
    maint.ticket_status     = 'open';
    maint.date_reported     = new GlideDateTime();
    maint.issue_description = current.close_notes;

    var grp = new GlideRecord('sys_user_group');
    grp.addQuery('name', 'Workspace Maintenance Team');
    grp.query();
    if (grp.next()) {
        maint.assignment_group = grp.sys_id;
    }

    maint.insert();
    gs.addInfoMessage('Maintenance ticket created successfully.');
    action.setRedirectURL(current);
})();
